void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {  
    // Assuming resultMap contains two keys "left" and "right" with corresponding lists of vertices
    List<V> leftVertices = (List<V>) resultMap.get("left");
    List<V> rightVertices = (List<V>) resultMap.get("right");

    if (leftVertices == null || rightVertices == null) {
        throw new IllegalArgumentException("Result map must contain 'left' and 'right' lists of vertices");
    }

    // Add all vertices to the target graph
    for (V vertex : leftVertices) {
        target.addVertex(vertex);
    }
    for (V vertex : rightVertices) {
        target.addVertex(vertex);
    }

    // Add edges between all vertices from left and right sets
    for (V leftVertex : leftVertices) {
        for (V rightVertex : rightVertices) {
            target.addEdge(leftVertex, rightVertex);
        }
    }
}

