    }

    V startVertex = graph.getEdgeSource(edgeList.get(0));
    List<V> vertexList = new ArrayList<>();
    vertexList.add(startVertex);

    while (!edgeList.isEmpty()) {
        E nextEdge = null;
        for (E edge : edgeList) {
            if (graph.getEdgeSource(edge).equals(vertexList.get(vertexList.size() - 1))) {
                nextEdge = edge;
                break;
            }
        }
        if (nextEdge == null) {
            break;
        }
        vertexList.add(graph.getEdgeTarget(nextEdge));
        edgeList.remove(nextEdge);
    }

    return new GraphPathImpl<>(graph, vertexList, calculatePathWeight(vertexList, graph));
}

private double calculatePathWeight(List<V> vertexList, Graph<V, E> graph) {
    double weight = 0.0;
    for (int i = 0; i < vertexList.size() - 1; i++) {
        weight += graph.getEdgeWeight(graph.getEdge(vertexList.get(i), vertexList.get(i + 1)));
    }
    // Add weight of the edge connecting the last vertex back to the start vertex
    weight += graph.getEdgeWeight(graph.getEdge(vertexList.get(vertexList.size() - 1), vertexList.get(0)));
    return weight;
}

