void addToClassPath(Vector<URL> cpV, String dir) {
    File dirF = new File(dir);
    if (dirF.exists() && dirF.isDirectory()) {
        File[] jars = dirF.listFiles(new FilenameFilter() {
            public boolean accept(File dir, String name) {
                return name.endsWith(".jar");
            }
        });
        if (jars != null) {
            for (File jar : jars) {
                try {
                    cpV.add(jar.toURI().toURL());
                } catch (MalformedURLException e) {
                    e.printStackTrace();
                }
            }
        }
    }
}

